SELECT tags, time_series FROM (SELECT tags, arraySort(item -> item.1, arrayFlatten(groupArray(time_series))) AS time_series FROM (SELECT if(arrayStringConcat([tupleElement(arrayFirst(tag -> tag.1 = 'job', arrayPushBack(label_child.tags, tuple('job', ''))), 2), tupleElement(arrayFirst(tag -> tag.1 = 'instance', arrayPushBack(label_child.tags, tuple('instance', ''))), 2)], '-') = '', arrayFilter(tag -> tag.1 != 'combined', label_child.tags), arraySort(tag -> tag.1, arrayPushBack(arrayFilter(tag -> tag.1 != 'combined', label_child.tags), tuple('combined', arrayStringConcat([tupleElement(arrayFirst(tag -> tag.1 = 'job', arrayPushBack(label_child.tags, tuple('job', ''))), 2), tupleElement(arrayFirst(tag -> tag.1 = 'instance', arrayPushBack(label_child.tags, tuple('instance', ''))), 2)], '-'))))) AS tags, label_child.time_series AS time_series FROM (SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
    SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({label_child_start_ms:Int64}, {label_child_end_ms:Int64} + {label_child_step_ms:Int64}, {label_child_step_ms:Int64}))) AS eval_ts FROM (
        SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {label_child_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({label_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({label_child_required_end_ms:Int64})
    ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({label_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({label_child_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({label_child_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({label_child_offset_ms:Int64} + {label_child_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
) GROUP BY tags ORDER BY tags) AS label_child) AS label_rows GROUP BY tags) AS label_series WHERE throwIf(arrayExists((idx, point) -> if(idx = 1, 0, tupleElement(point, 1) = tupleElement(arrayElement(time_series, idx - 1), 1)), arrayEnumerate(time_series), time_series), 'vector cannot contain metrics with the same labelset') = 0 ORDER BY tags ASC
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
